-- Publish a corrected immutable RED-TEST version whose 49 item texts match the approved TTS audio.
begin;
create temporary table red_test_tts_text_sync (session_number integer not null,item_number integer not null,text_vi text not null,text_en text not null,primary key (session_number,item_number)) on commit drop;
insert into red_test_tts_text_sync values
(1,1,'buổi sáng / ngon lành','morning / delicious'),(1,2,'xe đạp / đi','bicycle / ride'),(1,3,'quyển sách / đọc','book / read'),(1,4,'âm nhạc / thư giãn','music / relax'),(1,5,'gia đình / ấm áp','family / warm'),(1,6,'công viên / chạy','park / run'),(1,7,'bãi biển / đẹp','beach / beautiful'),
(2,1,'Duyệt / do đó / đề xuất','Approve / therefore / proposal'),(2,2,', có thể nói vậy / ví dụ / rõ ràng',', so to speak / for example / clear'),(2,3,'Cải thiện / bởi thế / chất lượng','Work on / for that reason / quality'),(2,4,'Quản trị / sau đó / hiệu quả','Management / then / efficiently'),(2,5,'Nguyên tắc / ngoài ra / tuân thủ','Philosophy / besides / follow'),(2,6,'Dài dòng / cuối cùng / trọng tâm','Lengthy / finally / main point'),(2,7,'Dầu gió / nếu không / dễ chịu','Medicated oil / otherwise / soothing'),
(3,1,'Cái máy lạnh / vì vậy / êm ru / ổn định','AC / so / quietly / stable'),(3,2,'Cứ thoải mái / mặc dù / cởi mở / ý kiến','Freely / although / openly / opinion'),(3,3,'Kỹ sư trưởng / đồng thời / đầu tàu / quyết đoán','Chief engineer / meanwhile / team leader / decisive'),(3,4,'Kỹ năng và khả năng / nói cách khác / mài giũa / mỗi ngày','Skill and ability / in other words / sharpen / daily'),(3,5,'Thực tập sinh / sau cùng / non tay / học hỏi','Intern / eventually / inexperienced / learn'),(3,6,'Có lẽ / trước đó / le lói / khả năng','Perhaps / before that / slight hope / possibility'),(3,7,'Duyệt / hơn nữa / bật đèn / kế hoạch','Approve / in addition / greenlight / plan'),
